import {
  ESCROW_STATUSES,
  PURCHASE_STATUSES,
  TERMINAL_STATUSES,
} from "@overflow/schemas";
import { sql, type SQL } from "drizzle-orm";
import {
  boolean,
  check,
  index,
  integer,
  jsonb,
  numeric,
  pgEnum,
  pgTable,
  text,
  timestamp,
  unique,
  uniqueIndex,
  type AnyPgColumn,
} from "drizzle-orm/pg-core";

// ---------------------------------------------------------------------------
// Conventions (docs/SPEC.md "Database tables", CLAUDE.md money rule)
// - Money columns are numeric(78,0) read as decimal strings. Never float.
// - Ids are text (uuid or slug) generated by the repositories.
// - Times are timestamptz; repositories convert Date <-> ISO string.
// ---------------------------------------------------------------------------

/** Integer atomic USDC units. Wide enough for uint256, no fractional digits. */
const money = (name: string) => numeric(name, { precision: 78, scale: 0, mode: "string" });
const nonNegative = (col: AnyPgColumn): SQL => sql`${col} >= 0`;
const ts = (name: string) => timestamp(name, { withTimezone: true, mode: "date" });

export const purchaseStatusEnum = pgEnum("purchase_status", PURCHASE_STATUSES);
export const escrowStatusEnum = pgEnum("escrow_status", ESCROW_STATUSES);

export const organizations = pgTable("organizations", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  departments: text("departments").array().notNull(),
  treasuryAddress: text("treasury_address"),
  /** True for the fictional demo company. */
  simulated: boolean("simulated").notNull().default(false),
  createdAt: ts("created_at").notNull().defaultNow(),
});

export const agents = pgTable(
  "agents",
  {
    id: text("id").primaryKey(),
    organizationId: text("organization_id")
      .notNull()
      .references(() => organizations.id),
    name: text("name").notNull(),
    department: text("department").notNull(),
    role: text("role").notNull(),
    /** Treasury node id; null until created onchain. */
    nodeId: integer("node_id"),
    key: text("key").notNull(),
    parentAgentId: text("parent_agent_id").references((): AnyPgColumn => agents.id),
    createdAt: ts("created_at").notNull().defaultNow(),
  },
  (t) => [index("agents_organization_idx").on(t.organizationId)],
);

export const missions = pgTable(
  "missions",
  {
    id: text("id").primaryKey(),
    organizationId: text("organization_id")
      .notNull()
      .references(() => organizations.id),
    goal: text("goal").notNull(),
    budget: money("budget").notNull(),
    rootNodeId: integer("root_node_id").notNull(),
    ownerAgentId: text("owner_agent_id").references(() => agents.id),
    status: text("status").notNull(),
    createdAt: ts("created_at").notNull().defaultNow(),
  },
  (t) => [check("missions_budget_nonneg", nonNegative(t.budget))],
);

export const resources = pgTable("resources", {
  id: text("id").primaryKey(),
  title: text("title").notNull(),
  url: text("url"),
  sellerId: text("seller_id").notNull(),
  productId: text("product_id").notNull(),
  /** Structured coverage (regions, dateRange, granularity, fields, format, asOf). */
  coverage: jsonb("coverage").notNull(),
  license: text("license").notNull(),
  price: money("price").notNull(),
  manifestHash: text("manifest_hash").notNull(),
  seats: integer("seats").notNull(),
  simulated: boolean("simulated").notNull().default(false),
  createdAt: ts("created_at").notNull().defaultNow(),
}, (t) => [check("resources_price_nonneg", nonNegative(t.price))]);

export const resourceRequests = pgTable(
  "resource_requests",
  {
    id: text("id").primaryKey(),
    missionId: text("mission_id")
      .notNull()
      .references(() => missions.id),
    agentId: text("agent_id")
      .notNull()
      .references(() => agents.id),
    status: text("status").notNull(),
    topic: text("topic").notNull(),
    regions: text("regions").array().notNull(),
    dateRange: jsonb("date_range").notNull(),
    granularity: text("granularity").notNull(),
    requiredFields: text("required_fields").array().notNull(),
    format: text("format").array().notNull(),
    license: text("license").notNull(),
    freshness: jsonb("freshness").notNull(),
    maxPrice: money("max_price").notNull(),
    createdAt: ts("created_at").notNull().defaultNow(),
  },
  (t) => [
    index("resource_requests_mission_idx").on(t.missionId),
    check("resource_requests_max_price_nonneg", nonNegative(t.maxPrice)),
  ],
);

export const purchaseGroups = pgTable("purchase_groups", {
  id: text("id").primaryKey(),
  missionId: text("mission_id")
    .notNull()
    .references(() => missions.id),
  resourceId: text("resource_id")
    .notNull()
    .references(() => resources.id),
  payingNodeId: integer("paying_node_id").notNull(),
  requestIds: text("request_ids").array().notNull(),
  mergeReason: text("merge_reason").notNull(),
  createdAt: ts("created_at").notNull().defaultNow(),
});

/** Statuses under which a (mission, resource) pair may have only one purchase. */
// drizzle-kit cannot inline bound parameters in an index predicate, so the
// terminal statuses are rendered as SQL literals. They are a fixed enum, not user input.
const activeStatusPredicate = (col: AnyPgColumn): SQL =>
  sql`${col} NOT IN ${sql.raw(`(${TERMINAL_STATUSES.map((s) => `'${s}'`).join(", ")})`)}`;

export const purchases = pgTable(
  "purchases",
  {
    id: text("id").primaryKey(),
    idempotencyKey: text("idempotency_key").notNull(),
    orderIdBytes32: text("order_id_bytes32").notNull(),
    missionId: text("mission_id")
      .notNull()
      .references(() => missions.id),
    resourceId: text("resource_id")
      .notNull()
      .references(() => resources.id),
    purchaseGroupId: text("purchase_group_id").references(() => purchaseGroups.id),
    buyerTreasury: text("buyer_treasury").notNull(),
    sellerAddress: text("seller_address").notNull(),
    escrowAddress: text("escrow_address").notNull(),
    chainId: integer("chain_id").notNull(),
    tokenAddress: text("token_address").notNull(),
    amount: money("amount").notNull(),
    payingNodeId: integer("paying_node_id").notNull(),
    participatingAgentIds: text("participating_agent_ids").array().notNull(),
    resourceManifestHash: text("resource_manifest_hash").notNull(),
    termsHash: text("terms_hash").notNull(),
    paymentPath: text("payment_path").notNull(),
    authorizationDigest: text("authorization_digest"),
    txHashes: text("tx_hashes").array().notNull(),
    oracleReason: text("oracle_reason"),
    status: purchaseStatusEnum("status").notNull(),
    authorizationExpiresAt: ts("authorization_expires_at").notNull(),
    createdAt: ts("created_at").notNull().defaultNow(),
    updatedAt: ts("updated_at").notNull().defaultNow(),
  },
  (t) => [
    unique("purchases_idempotency_key_unique").on(t.idempotencyKey),
    // One active purchase per (mission, resource); terminal rows do not count.
    uniqueIndex("purchases_active_mission_resource_uidx")
      .on(t.missionId, t.resourceId)
      .where(activeStatusPredicate(t.status)),
    index("purchases_mission_idx").on(t.missionId),
    index("purchases_status_idx").on(t.status),
    check("purchases_amount_nonneg", nonNegative(t.amount)),
  ],
);

export const allocations = pgTable(
  "allocations",
  {
    id: text("id").primaryKey(),
    purchaseId: text("purchase_id")
      .notNull()
      .references(() => purchases.id),
    agentId: text("agent_id")
      .notNull()
      .references(() => agents.id),
    department: text("department").notNull(),
    amount: money("amount").notNull(),
  },
  (t) => [
    index("allocations_purchase_idx").on(t.purchaseId),
    check("allocations_amount_nonneg", nonNegative(t.amount)),
  ],
);

export const chainTransactions = pgTable(
  "chain_transactions",
  {
    id: text("id").primaryKey(),
    purchaseId: text("purchase_id").references(() => purchases.id),
    txHash: text("tx_hash").notNull(),
    logIndex: integer("log_index").notNull(),
    blockNumber: money("block_number").notNull(),
    contractAddress: text("contract_address").notNull(),
    eventName: text("event_name").notNull(),
    args: jsonb("args").notNull(),
    observedAt: ts("observed_at").notNull().defaultNow(),
    confirmed: boolean("confirmed").notNull().default(false),
  },
  (t) => [
    unique("chain_transactions_tx_hash_log_index_unique").on(t.txHash, t.logIndex),
    index("chain_transactions_purchase_idx").on(t.purchaseId),
  ],
);

export const escrowOrders = pgTable(
  "escrow_orders",
  {
    id: text("id").primaryKey(),
    purchaseId: text("purchase_id")
      .notNull()
      .references(() => purchases.id),
    orderIdBytes32: text("order_id_bytes32").notNull(),
    escrowAddress: text("escrow_address").notNull(),
    sellerAddress: text("seller_address").notNull(),
    amount: money("amount").notNull(),
    bond: money("bond").notNull(),
    termsHash: text("terms_hash").notNull(),
    manifestHash: text("manifest_hash").notNull(),
    rootPlain: text("root_plain").notNull(),
    rootCipher: text("root_cipher").notNull(),
    keyCommitment: text("key_commitment").notNull(),
    revealDeadline: money("reveal_deadline").notNull(),
    challengeWindow: money("challenge_window").notNull(),
    sourceKey: text("source_key").notNull(),
    minTimestamp: money("min_timestamp").notNull(),
    status: escrowStatusEnum("status").notNull(),
    revealedKey: text("revealed_key"),
    refundReason: text("refund_reason"),
    createdAt: ts("created_at").notNull().defaultNow(),
    updatedAt: ts("updated_at").notNull().defaultNow(),
  },
  (t) => [
    unique("escrow_orders_purchase_id_unique").on(t.purchaseId),
    unique("escrow_orders_escrow_address_unique").on(t.escrowAddress),
    check("escrow_orders_amount_nonneg", nonNegative(t.amount)),
    check("escrow_orders_bond_nonneg", nonNegative(t.bond)),
  ],
);

/** Double-entry rows. One row per chain event (source_event_id unique). Never deleted. */
export const financialEntries = pgTable(
  "financial_entries",
  {
    id: text("id").primaryKey(),
    purchaseId: text("purchase_id").references(() => purchases.id),
    debitAccount: text("debit_account").notNull(),
    creditAccount: text("credit_account").notNull(),
    amount: money("amount").notNull(),
    memo: text("memo").notNull(),
    sourceEventId: text("source_event_id").notNull(),
    department: text("department"),
    txHash: text("tx_hash"),
    correctsEntryId: text("corrects_entry_id").references((): AnyPgColumn => financialEntries.id),
    postedAt: ts("posted_at").notNull().defaultNow(),
  },
  (t) => [
    unique("financial_entries_source_event_id_unique").on(t.sourceEventId),
    index("financial_entries_purchase_idx").on(t.purchaseId),
    check("financial_entries_amount_nonneg", nonNegative(t.amount)),
    check("financial_entries_accounts_differ", sql`${t.debitAccount} <> ${t.creditAccount}`),
  ],
);

export const activityEvents = pgTable(
  "activity_events",
  {
    id: text("id").primaryKey(),
    at: ts("at").notNull().defaultNow(),
    kind: text("kind").notNull(),
    message: text("message").notNull(),
    purchaseId: text("purchase_id").references(() => purchases.id),
    missionId: text("mission_id").references(() => missions.id),
    agentId: text("agent_id").references(() => agents.id),
    decodedRevert: text("decoded_revert"),
    txHash: text("tx_hash"),
    simulated: boolean("simulated").notNull().default(false),
  },
  (t) => [index("activity_events_at_idx").on(t.at)],
);

export const reservations = pgTable(
  "reservations",
  {
    id: text("id").primaryKey(),
    digest: text("digest").notNull(),
    purchaseId: text("purchase_id").references(() => purchases.id),
    nodeId: integer("node_id").notNull(),
    value: money("value").notNull(),
    validBefore: money("valid_before").notNull(),
    nonce: text("nonce").notNull(),
    status: text("status").notNull(),
    txHash: text("tx_hash"),
    createdAt: ts("created_at").notNull().defaultNow(),
    updatedAt: ts("updated_at").notNull().defaultNow(),
  },
  (t) => [
    unique("reservations_digest_unique").on(t.digest),
    check("reservations_value_nonneg", nonNegative(t.value)),
  ],
);

export const samples = pgTable(
  "samples",
  {
    id: text("id").primaryKey(),
    purchaseId: text("purchase_id")
      .notNull()
      .references(() => purchases.id),
    indices: integer("indices").array().notNull(),
    verdict: text("verdict").notNull(),
    reason: text("reason").notNull(),
    /** Model confidence 0..1 stored as text to keep the "no float columns" rule simple to audit. */
    confidence: text("confidence"),
    promptHash: text("prompt_hash"),
    outputHash: text("output_hash"),
    createdAt: ts("created_at").notNull().defaultNow(),
  },
  (t) => [index("samples_purchase_idx").on(t.purchaseId)],
);

export const sellerHistory = pgTable("seller_history", {
  sellerAddress: text("seller_address").primaryKey(),
  sellerId: text("seller_id"),
  orders: integer("orders").notNull().default(0),
  onTimeReveals: integer("on_time_reveals").notNull().default(0),
  lateReveals: integer("late_reveals").notNull().default(0),
  provenCheats: integer("proven_cheats").notNull().default(0),
  flagged: boolean("flagged").notNull().default(false),
  updatedAt: ts("updated_at").notNull().defaultNow(),
});

export const exceptions = pgTable(
  "exceptions",
  {
    id: text("id").primaryKey(),
    type: text("type").notNull(),
    reason: text("reason").notNull(),
    amount: money("amount"),
    status: text("status").notNull(),
    purchaseId: text("purchase_id").references(() => purchases.id),
    resolvedBy: text("resolved_by"),
    openedAt: ts("opened_at").notNull().defaultNow(),
    resolvedAt: ts("resolved_at"),
  },
  (t) => [
    index("exceptions_status_idx").on(t.status),
    check("exceptions_amount_nonneg", sql`${t.amount} IS NULL OR ${t.amount} >= 0`),
  ],
);

export const controllerRequests = pgTable("controller_requests", {
  id: text("id").primaryKey(),
  /** ControllerAction discriminated union, validated by Zod at the boundary. */
  action: jsonb("action").notNull(),
  requestedBy: text("requested_by").notNull(),
  reason: text("reason").notNull(),
  status: text("status").notNull(),
  txHash: text("tx_hash"),
  createdAt: ts("created_at").notNull().defaultNow(),
  resolvedAt: ts("resolved_at"),
});

export const TABLE_NAMES = [
  "organizations",
  "missions",
  "agents",
  "resource_requests",
  "resources",
  "purchase_groups",
  "allocations",
  "purchases",
  "chain_transactions",
  "escrow_orders",
  "financial_entries",
  "activity_events",
  "reservations",
  "samples",
  "seller_history",
  "exceptions",
  "controller_requests",
] as const;
